import{_ as r,o as a,c as t,a2 as n}from"./chunks/framework.CdvW4CUT.js";const d=JSON.parse('{"title":"Kernel 日报 2026-10-22","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/10/22.md","filePath":"notes/kernel-digest/2026/10/22.md"}'),o={name:"notes/kernel-digest/2026/10/22.md"};function l(i,e,s,c,h,u){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="kernel-日报-2026-10-22" tabindex="-1">Kernel 日报 2026-10-22 <a class="header-anchor" href="#kernel-日报-2026-10-22" aria-label="Permalink to &quot;Kernel 日报 2026-10-22&quot;">​</a></h1><blockquote><p>生成时间：2026-10-22T01:32:57Z｜共 26 条</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="linus-torvalds-eliminates-unsafe-get-user-put-user-functions-in-linux-7-4" tabindex="-1"><a href="https://www.phoronix.com/news/Linus-Kills-Get-Put-User-Linux" target="_blank" rel="noreferrer">Linus Torvalds Eliminates Unsafe __get_user() &amp; __put_user() Functions In Linux 7.4</a> <a class="header-anchor" href="#linus-torvalds-eliminates-unsafe-get-user-put-user-functions-in-linux-7-4" aria-label="Permalink to &quot;[Linus Torvalds Eliminates Unsafe __get_user() &amp; __put_user() Functions In Linux 7.4](https://www.phoronix.com/news/Linus-Kills-Get-Put-User-Linux)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Linus Torvalds 在 Linux 7.4 中移除了历史上不安全的 __get_user() 和 __put_user() 内核函数。这些函数缺少 access_ok() 地址校验，容易被误用导致安全问题。此次清理是 Linus 近期亲自提交补丁（部分借助 Claude Code 辅助）的延续。</p><blockquote><p><strong>学习价值</strong>：展示了内核 API 安全演进的典型案例，学习者可借此理解 user space 内存访问接口的安全边界与历史包袱清理过程。</p></blockquote><h3 id="hash-based-module-integrity-for-reproducible-distributions" tabindex="-1"><a href="https://lwn.net/Articles/1100026/" target="_blank" rel="noreferrer">[$] Hash-based module integrity for reproducible distributions</a> <a class="header-anchor" href="#hash-based-module-integrity-for-reproducible-distributions" aria-label="Permalink to &quot;[[$] Hash-based module integrity for reproducible distributions](https://lwn.net/Articles/1100026/)&quot;">​</a></h3><p><em>jake｜lwn｜<strong>LWN 订阅文章，仅预览</strong>｜其他动态</em></p><p>Thomas Weißschuh 在 2026 Linux Plumbers Conference 上介绍了基于哈希的内核模块完整性校验补丁：在保证可复现构建（reproducible builds）的前提下，为内核模块提供完整性保证。补丁集历经多次修订，他还讨论了后续可能的改进方向。</p><blockquote><p><strong>学习价值</strong>：深入展示 modules 完整性验证与 reproducible builds 的结合设计，是理解内核供应链安全的优秀案例。</p></blockquote><h3 id="upstreaming-tyr-rust-drm-and-the-linux-kernel-collabora" tabindex="-1"><a href="https://lwn.net/Articles/1102024/" target="_blank" rel="noreferrer">Upstreaming Tyr: Rust, DRM, and the Linux Kernel (Collabora)</a> <a class="header-anchor" href="#upstreaming-tyr-rust-drm-and-the-linux-kernel-collabora" aria-label="Permalink to &quot;[Upstreaming Tyr: Rust, DRM, and the Linux Kernel (Collabora)](https://lwn.net/Articles/1102024/)&quot;">​</a></h3><p><em>corbet｜lwn｜Rust in Linux</em></p><p>Collabora 博客更新了 Arm Mali GPU 的 Rust 驱动 Tyr 的上游化进展。最大挑战在于 Rust 内核抽象层与驱动接口本身仍在演进，Tyr 已多次重写以适配不断变化的 API，job scheduling 等能力也因抽象层尚在评审而停滞。</p><blockquote><p><strong>学习价值</strong>：真实呈现了在 Rust 内核抽象尚未成熟时编写驱动的代价与流程，对关注 Rust in Linux 与 DRM 子系统演进的学习者极具参考价值。</p></blockquote><h3 id="patch-v3-0-4-sparc64-d-cache-alias-flushing-fixes" tabindex="-1"><a href="https://lore.kernel.org/all/cover.1792609488.git.kaloz@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 0/4] sparc64: D-cache alias flushing fixes</a> <a class="header-anchor" href="#patch-v3-0-4-sparc64-d-cache-alias-flushing-fixes" aria-label="Permalink to &quot;[[PATCH v3 0/4] sparc64: D-cache alias flushing fixes](https://lore.kernel.org/all/cover.1792609488.git.kaloz@kernel.org/)&quot;">​</a></h3><p><em>Imre Kaloz (<a href="mailto:kaloz@kernel.org" target="_blank" rel="noreferrer">kaloz@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>这是 sparc64 D-cache alias 刷新修复系列的 cover letter，针对具有 virtually indexed L1 D-cache 的 Spitfire 与 Cheetah。系列包含：xcall_deliver() 无目标时提前返回、只刷新 PTE 映射的单页而非整个 folio（在 Sun Fire V240 上把大 folio 的 colour-changing mremap() 从 7.3 秒降下来）、以及实现此前为空操作的 flush_cache_vmap()/flush_cache_vunmap()。</p><blockquote><p><strong>学习价值</strong>：适合了解 VIPT cache alias 问题、架构相关 cache 维护接口与 folio 化带来的性能回归排查思路。</p></blockquote><h3 id="linux-7-4-begins-landing-patches-to-speed-up-the-kernel-build-process" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-Kbuild" target="_blank" rel="noreferrer">Linux 7.4 Begins Landing Patches To Speed Up The Kernel Build Process</a> <a class="header-anchor" href="#linux-7-4-begins-landing-patches-to-speed-up-the-kernel-build-process" aria-label="Permalink to &quot;[Linux 7.4 Begins Landing Patches To Speed Up The Kernel Build Process](https://www.phoronix.com/news/Linux-7.4-Kbuild)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Arm 工程师 Lorenzo Stoakes 编写的一批补丁已开始合入 Linux 7.4，旨在加速内核构建过程，可显著缩短内核构建时间。</p><blockquote><p><strong>学习价值</strong>：对关注内核构建系统（Kbuild）优化与开发者日常工作流的学习者有直接实用价值。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（8 条）</li><li><strong>网络</strong>（1 条）</li><li><strong>Rust in Linux</strong>（2 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>核心内核</strong>（1 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（12 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="damon-beer-coffee-tea-chat-reminder-for-the-week-of-2026-10-26" tabindex="-1"><a href="https://lore.kernel.org/all/20261022002031.87137-1-sj@kernel.org/" target="_blank" rel="noreferrer">DAMON Beer/Coffee/Tea chat reminder for the week of 2026-10-26</a> <a class="header-anchor" href="#damon-beer-coffee-tea-chat-reminder-for-the-week-of-2026-10-26" aria-label="Permalink to &quot;[DAMON Beer/Coffee/Tea chat reminder for the week of 2026-10-26](https://lore.kernel.org/all/20261022002031.87137-1-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>这是 DAMON（Data Access MONitor）社区每周 Beer/Coffee/Tea 线上交流会的例行提醒，列出了 2026-10-26 起的多个会议时间段。会议由 SJ Park 组织，供 DAMON 开发者和用户讨论数据访问监控相关话题。</p><blockquote><p><strong>学习价值</strong>：提示学习者 DAMON 子系统有活跃的社区交流渠道，可关注其开发动态。</p></blockquote><h3 id="patch-v1-2-2-mm-multi-gen-lru-remove-get-lruvec" tabindex="-1"><a href="https://lore.kernel.org/all/20261021235606.89545-2-sidchintamaneni@gmail.com/" target="_blank" rel="noreferrer">[PATCH v1 2/2] mm: multi-gen LRU: remove get_lruvec()</a> <a class="header-anchor" href="#patch-v1-2-2-mm-multi-gen-lru-remove-get-lruvec" aria-label="Permalink to &quot;[[PATCH v1 2/2] mm: multi-gen LRU: remove get_lruvec()](https://lore.kernel.org/all/20261021235606.89545-2-sidchintamaneni@gmail.com/)&quot;">​</a></h3><p><em>Siddharth Chintamaneni (<a href="mailto:sidchintamaneni@gmail.com" target="_blank" rel="noreferrer">sidchintamaneni@gmail.com</a>)｜linux-mm</em></p><p>该补丁移除 multi-gen LRU 中的 get_lruvec() 辅助函数。该函数最初为防护未初始化 NUMA 节点的 NULL NODE_DATA() 而引入，但在相关 NULL 检查被移除后，它已退化为 mem_cgroup_lruvec() 的薄封装。补丁在所有调用点直接改用 mem_cgroup_lruvec()。</p><blockquote><p><strong>学习价值</strong>：典型的内核代码清理案例，可学习如何识别并消除冗余的间接层，以及理解 lruvec 与 memcg 的关系。</p></blockquote><h3 id="patch-v1-1-2-mm-multi-gen-lru-use-mem-cgroup-lruvec-in-get-lruvec" tabindex="-1"><a href="https://lore.kernel.org/all/20261021235606.89545-1-sidchintamaneni@gmail.com/" target="_blank" rel="noreferrer">[PATCH v1 1/2] mm: multi-gen LRU: use mem_cgroup_lruvec() in get_lruvec()</a> <a class="header-anchor" href="#patch-v1-1-2-mm-multi-gen-lru-use-mem-cgroup-lruvec-in-get-lruvec" aria-label="Permalink to &quot;[[PATCH v1 1/2] mm: multi-gen LRU: use mem_cgroup_lruvec() in get_lruvec()](https://lore.kernel.org/all/20261021235606.89545-1-sidchintamaneni@gmail.com/)&quot;">​</a></h3><p><em>Siddharth Chintamaneni (<a href="mailto:sidchintamaneni@gmail.com" target="_blank" rel="noreferrer">sidchintamaneni@gmail.com</a>)｜linux-mm</em></p><p>该补丁让 get_lruvec() 直接委托给 mem_cgroup_lruvec()，与 Andrew Morton 指出的 lru_gen_shrink_node() 模式保持一致。此前在命令行禁用 memcg（cgroup_disable=memory）时会直接返回 &amp;pgdat-&gt;__lruvec，绕过 lruvec-&gt;pgdat 的初始化；但由于所有调用点都在 kswapd_init() 之后运行，实际不构成运行时 bug。</p><blockquote><p><strong>学习价值</strong>：展示了内核代码中潜在初始化顺序问题的分析过程，对理解 memcg 与 lruvec 初始化时序很有价值。</p></blockquote><h3 id="patch-v3-4-4-mm-pass-the-number-of-ptes-to-move-pte" tabindex="-1"><a href="https://lore.kernel.org/all/2bc50d2a6829b49ee909e5bb943244859661a40b.1792609488.git.kaloz@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 4/4] mm: pass the number of PTEs to move_pte()</a> <a class="header-anchor" href="#patch-v3-4-4-mm-pass-the-number-of-ptes-to-move-pte" aria-label="Permalink to &quot;[[PATCH v3 4/4] mm: pass the number of PTEs to move_pte()](https://lore.kernel.org/all/2bc50d2a6829b49ee909e5bb943244859661a40b.1792609488.git.kaloz@kernel.org/)&quot;">​</a></h3><p><em>Imre Kaloz (<a href="mailto:kaloz@kernel.org" target="_blank" rel="noreferrer">kaloz@kernel.org</a>)｜linux-mm</em></p><p>自 commit f822a9a81a31 引入 mremap() 的 PTE 批量优化后，move_ptes() 一次搬移一批 PTE，但只以首个 PTE 调用 move_pte()。sparc64 是唯一重写 move_pte() 的架构，会在 PTE 颜色变化时刷新 D-cache，因此批内其他页面可能残留旧颜色的 cache line。该补丁将 nr_ptes 传递给 move_pte() 以修复此问题。</p><blockquote><p><strong>学习价值</strong>：深入展示了 PTE 批量化优化与架构相关 cache 一致性（VIPT D-cache 颜色问题）之间的微妙交互，是学习跨架构内核代码的优质案例。</p></blockquote><h3 id="patch-v3-3-4-sparc64-flush-vmalloc-ranges-from-the-d-cache-on-map-and-unmap" tabindex="-1"><a href="https://lore.kernel.org/all/55b4691ea87be7f4a679197bc2ec35b81b45d233.1792609488.git.kaloz@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 3/4] sparc64: flush vmalloc ranges from the D-cache on map and unmap</a> <a class="header-anchor" href="#patch-v3-3-4-sparc64-flush-vmalloc-ranges-from-the-d-cache-on-map-and-unmap" aria-label="Permalink to &quot;[[PATCH v3 3/4] sparc64: flush vmalloc ranges from the D-cache on map and unmap](https://lore.kernel.org/all/55b4691ea87be7f4a679197bc2ec35b81b45d233.1792609488.git.kaloz@kernel.org/)&quot;">​</a></h3><p><em>Imre Kaloz (<a href="mailto:kaloz@kernel.org" target="_blank" rel="noreferrer">kaloz@kernel.org</a>)｜linux-mm</em></p><p>sparc64 的 Spitfire/Cheetah L1 D-cache 以 VA bit 13 索引，但 flush_cache_vmap()/flush_cache_vunmap() 是空操作，导致 vmalloc 地址加载的 cache line 在 unmap 后残留，可能读到过期数据，在 UltraSPARC III 上会损坏 BPF 程序和模块数据。补丁在 map/unmap 时逐页在所有 CPU 上刷新，或当范围超过 cache 大小时通过跨 CPU 调用整体刷新 D-cache。</p><blockquote><p><strong>学习价值</strong>：罕见的 sparc64 cache 一致性修复案例，深入讲解了虚拟索引 cache 的别名问题及跨 CPU TLB/cache 刷新机制，对理解架构级内存一致性极有价值。</p></blockquote><h3 id="patch-v3-2-4-sparc64-flush-only-the-aliased-page-not-its-whole-folio" tabindex="-1"><a href="https://lore.kernel.org/all/65ae69ec96f854a010ef8407144958cc290a1bf2.1792609488.git.kaloz@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 2/4] sparc64: flush only the aliased page, not its whole folio</a> <a class="header-anchor" href="#patch-v3-2-4-sparc64-flush-only-the-aliased-page-not-its-whole-folio" aria-label="Permalink to &quot;[[PATCH v3 2/4] sparc64: flush only the aliased page, not its whole folio](https://lore.kernel.org/all/65ae69ec96f854a010ef8407144958cc290a1bf2.1792609488.git.kaloz@kernel.org/)&quot;">​</a></h3><p><em>Imre Kaloz (<a href="mailto:kaloz@kernel.org" target="_blank" rel="noreferrer">kaloz@kernel.org</a>)｜linux-mm</em></p><p>该补丁修正 sparc64 在转换为 folio 后引入的过度刷新问题：move_pte() 与 tlb_batch_add() 每处理一个 PTE 就刷新整个 folio 内所有页的 D-cache，导致大 folio 映射区间中每页被重复刷新多次。在 SMP 上，Spitfire/Cheetah 每次页刷新都是一次向所有在线 CPU 的 cross-call，开销巨大。补丁改为只刷新该 PTE 实际映射的那一页，并把 flush_dcache_folio_all() 还原为 flush_dcache_page_all()。</p><blockquote><p><strong>学习价值</strong>：展示了 folio 转换中容易忽略的“按 PTE 调用 vs 按页刷新”语义差异，以及 D-cache alias 与 cross-call 成本的实际影响。</p></blockquote><h3 id="patch-v3-1-4-sparc64-skip-the-trap-block-in-xcall-deliver-when-there-is-no-target" tabindex="-1"><a href="https://lore.kernel.org/all/3bf5d270153bf6b8efb1673a9500df826ec28678.1792609488.git.kaloz@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 1/4] sparc64: skip the trap block in xcall_deliver() when there is no target</a> <a class="header-anchor" href="#patch-v3-1-4-sparc64-skip-the-trap-block-in-xcall-deliver-when-there-is-no-target" aria-label="Permalink to &quot;[[PATCH v3 1/4] sparc64: skip the trap block in xcall_deliver() when there is no target](https://lore.kernel.org/all/3bf5d270153bf6b8efb1673a9500df826ec28678.1792609488.git.kaloz@kernel.org/)&quot;">​</a></h3><p><em>Imre Kaloz (<a href="mailto:kaloz@kernel.org" target="_blank" rel="noreferrer">kaloz@kernel.org</a>)｜linux-mm</em></p><p>xcall_deliver() 在尚未确认目标 CPU 掩码前就通过 trap block 的物理地址写入 mondo 数据与目标列表，而这些地址在 init_IRQ() 初始化前为 0，早期 cross call 会写到物理地址 0。补丁在掩码中没有其他在线 CPU 时提前返回，避免触碰 trap block。</p><blockquote><p><strong>学习价值</strong>：典型的早期启动阶段初始化顺序陷阱，说明 SMP cross-call 路径在只有 boot CPU 在线时的边界条件。</p></blockquote><h3 id="patch-v3-0-4-sparc64-d-cache-alias-flushing-fixes-1" tabindex="-1"><a href="https://lore.kernel.org/all/cover.1792609488.git.kaloz@kernel.org/" target="_blank" rel="noreferrer">[PATCH v3 0/4] sparc64: D-cache alias flushing fixes</a> <a class="header-anchor" href="#patch-v3-0-4-sparc64-d-cache-alias-flushing-fixes-1" aria-label="Permalink to &quot;[[PATCH v3 0/4] sparc64: D-cache alias flushing fixes](https://lore.kernel.org/all/cover.1792609488.git.kaloz@kernel.org/)&quot;">​</a></h3><p><em>Imre Kaloz (<a href="mailto:kaloz@kernel.org" target="_blank" rel="noreferrer">kaloz@kernel.org</a>)｜linux-mm</em></p><p>这是 sparc64 D-cache alias 刷新修复系列的 cover letter，针对具有 virtually indexed L1 D-cache 的 Spitfire 与 Cheetah。系列包含：xcall_deliver() 无目标时提前返回、只刷新 PTE 映射的单页而非整个 folio（在 Sun Fire V240 上把大 folio 的 colour-changing mremap() 从 7.3 秒降下来）、以及实现此前为空操作的 flush_cache_vmap()/flush_cache_vunmap()。</p><blockquote><p><strong>学习价值</strong>：适合了解 VIPT cache alias 问题、架构相关 cache 维护接口与 folio 化带来的性能回归排查思路。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="patch-net-v3-tipc-fix-refcount-panic-in-tipc-rcv-when-receiving-shared-skb" tabindex="-1"><a href="https://lore.kernel.org/all/20261022011539.6882-1-tung.quang.nguyen@est.tech/" target="_blank" rel="noreferrer">[PATCH net v3] tipc: fix refcount panic in tipc_rcv() when receiving shared skb</a> <a class="header-anchor" href="#patch-net-v3-tipc-fix-refcount-panic-in-tipc-rcv-when-receiving-shared-skb" aria-label="Permalink to &quot;[[PATCH net v3] tipc: fix refcount panic in tipc_rcv() when receiving shared skb](https://lore.kernel.org/all/20261022011539.6882-1-tung.quang.nguyen@est.tech/)&quot;">​</a></h3><p><em>Tung Nguyen (tung.quang.nguyen@est.tech)｜netdev</em></p><p>TIPC 假设收到的 skb 不与其它使用者共享，但 syzbot 报告收到 shared skb 时在 tipc_rcv() 路径触发 refcount panic，栈显示 pskb_expand_head()/__pskb_pull_tail()/skb_cow_data() 经 tipc_aead_decrypt() 被调用。根因是本地投递 hook 使 skb 被共享，而 TIPC 未做 skb 拷贝/展开保护。</p><blockquote><p><strong>学习价值</strong>：有助于理解 skb 共享语义、skb_cow_data() 的作用以及网络协议栈中 refcount 类崩溃的定位方法。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="upstreaming-tyr-rust-drm-and-the-linux-kernel-collabora-1" tabindex="-1"><a href="https://lwn.net/Articles/1102024/" target="_blank" rel="noreferrer">Upstreaming Tyr: Rust, DRM, and the Linux Kernel (Collabora)</a> <a class="header-anchor" href="#upstreaming-tyr-rust-drm-and-the-linux-kernel-collabora-1" aria-label="Permalink to &quot;[Upstreaming Tyr: Rust, DRM, and the Linux Kernel (Collabora)](https://lwn.net/Articles/1102024/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>Collabora 博客更新了 Arm Mali GPU 的 Rust 驱动 Tyr 的上游化进展。最大挑战在于 Rust 内核抽象层与驱动接口本身仍在演进，Tyr 已多次重写以适配不断变化的 API，job scheduling 等能力也因抽象层尚在评审而停滞。</p><blockquote><p><strong>学习价值</strong>：真实呈现了在 Rust 内核抽象尚未成熟时编写驱动的代价与流程，对关注 Rust in Linux 与 DRM 子系统演进的学习者极具参考价值。</p></blockquote><h3 id="git-pull-rust-i2c-next-for-7-4" tabindex="-1"><a href="https://lore.kernel.org/all/179260155969.2966.15552703862037914616@linux.dev/" target="_blank" rel="noreferrer">[GIT PULL] rust-i2c-next for 7.4</a> <a class="header-anchor" href="#git-pull-rust-i2c-next-for-7-4" aria-label="Permalink to &quot;[[GIT PULL] rust-i2c-next for 7.4](https://lore.kernel.org/all/179260155969.2966.15552703862037914616@linux.dev/)&quot;">​</a></h3><p><em>Igor Korotin (igor.korotin@linux.dev)｜rust-for-linux</em></p><p>这是面向 7.4 合并窗口的 rust-i2c-next 拉取请求，只包含一个修复而非清理：移除 &amp;I2cClient 的 TryFrom&lt;&amp;Device&gt; 实现，以修复 KASAN 报告的 use-after-free。</p><blockquote><p><strong>学习价值</strong>：可作为 Rust for Linux 抽象层中生命周期与类型转换设计如何引发 UAF 的具体案例。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="snapdragon-x2-performance-on-linux-exceeding-expectations-in-initial-benchmarks" tabindex="-1"><a href="https://www.phoronix.com/review/snapdragon-x2-linux" target="_blank" rel="noreferrer">Snapdragon X2 Performance On Linux Exceeding Expectations In Initial Benchmarks</a> <a class="header-anchor" href="#snapdragon-x2-performance-on-linux-exceeding-expectations-in-initial-benchmarks" aria-label="Permalink to &quot;[Snapdragon X2 Performance On Linux Exceeding Expectations In Initial Benchmarks](https://www.phoronix.com/review/snapdragon-x2-linux)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Phoronix 使用新的 Ubuntu 26.10 X1E Concept ISO 对 Qualcomm Snapdragon X2 Elite Extreme（华硕 Zenbook A16 笔型本）进行了首批 Linux 基准测试。结果显示其 Linux 性能超出预期，表明 ARM 笔记本平台的内核支持日趋成熟。</p><blockquote><p><strong>学习价值</strong>：对了解新兴 ARM SoC 平台的 Linux 支持现状和性能水平有参考价值，但技术深度有限。</p></blockquote><h2 id="核心内核" tabindex="-1">核心内核 <a class="header-anchor" href="#核心内核" aria-label="Permalink to &quot;核心内核&quot;">​</a></h2><h3 id="amd-working-on-ryzen-overclocking-driver-for-linux" tabindex="-1"><a href="https://www.phoronix.com/news/AMD-AOD-Overclocking-Linux" target="_blank" rel="noreferrer">AMD Working On Ryzen Overclocking Driver For Linux</a> <a class="header-anchor" href="#amd-working-on-ryzen-overclocking-driver-for-linux" aria-label="Permalink to &quot;[AMD Working On Ryzen Overclocking Driver For Linux](https://www.phoronix.com/news/AMD-AOD-Overclocking-Linux)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 发布了 Linux 内核补丁，实现 AOD（AMD Overclocking Driver），为 Ryzen 处理器提供官方超频支持。这是 Linux 社区长期期待的、类似 Windows 上 Ryzen Master 的内核级超频驱动。该驱动将允许用户在 Linux 下调整 CPU 频率和电压等参数。</p><blockquote><p><strong>学习价值</strong>：展示了硬件厂商驱动进入主线内核的流程，对学习驱动开发与硬件接口（MSR 等）有一定参考意义。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="next-20261021-linux-next" tabindex="-1"><a href="https://www.kernel.org/#kernel.org-linux-next-next-20261021-2026-10-21" target="_blank" rel="noreferrer">next-20261021: linux-next</a> <a class="header-anchor" href="#next-20261021-linux-next" aria-label="Permalink to &quot;[next-20261021: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261021-2026-10-21)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 快照 next-20261021 的发布通告，日期为 2026-10-21，无额外内容。</p><blockquote><p><strong>学习价值</strong>：用于跟踪 linux-next 每日快照版本，便于对照某个补丁何时进入集成测试树。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="lwn-net-weekly-edition-for-october-22-2026" tabindex="-1"><a href="https://lwn.net/Articles/1100612/" target="_blank" rel="noreferrer">[$] LWN.net Weekly Edition for October 22, 2026</a> <a class="header-anchor" href="#lwn-net-weekly-edition-for-october-22-2026" aria-label="Permalink to &quot;[[$] LWN.net Weekly Edition for October 22, 2026](https://lwn.net/Articles/1100612/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>本期 LWN 周刊涵盖 Android vendor hooks、可复现构建与内核完整性、Rust 数据结构、NFS 服务器变更、为 PID 1 设置 no_new_privs、Rust XArray 与跨 crate 声明、7.3 版本统计等话题。简讯部分包括 eMudhra CA 被攻破、PHP RCE 漏洞、Node.js 与 musl 漏洞、OpenBSD 8.0 与 Ubuntu 26.10 发布等。</p><blockquote><p><strong>学习价值</strong>：作为内核学习者的每周索引，可从中快速定位 Rust 抽象层、内核完整性与调度等专题的深入报道入口。</p></blockquote><h3 id="today-s-php-security-release-and-how-we-re-strengthening-php-security-php-foundation" tabindex="-1"><a href="https://lwn.net/Articles/1102060/" target="_blank" rel="noreferrer">Today&#39;s PHP Security Release, and How We&#39;re Strengthening PHP Security (PHP Foundation)</a> <a class="header-anchor" href="#today-s-php-security-release-and-how-we-re-strengthening-php-security-php-foundation" aria-label="Permalink to &quot;[Today&#39;s PHP Security Release, and How We&#39;re Strengthening PHP Security (PHP Foundation)](https://lwn.net/Articles/1102060/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>PHP 基金会发文解释本次披露的漏洞成因及修复拖延的原因：为解决 OOM 问题，安全团队提出了多个竞争方案，但各自存在向后兼容性破坏、新的 DoS 风险或需协调大量第三方扩展等权衡，基于共识的决策机制难以下决心。文章还阐述了 PHP 安全流程的后续强化计划。</p><blockquote><p><strong>学习价值</strong>：展示了大型开源项目安全响应中的工程权衡与流程困境，对理解内核等项目的安全发布流程有借鉴意义。</p></blockquote><h3 id="more-vulnerabilities-in-widely-deployed-software" tabindex="-1"><a href="https://lwn.net/Articles/1102044/" target="_blank" rel="noreferrer">More vulnerabilities in widely deployed software</a> <a class="header-anchor" href="#more-vulnerabilities-in-widely-deployed-software" aria-label="Permalink to &quot;[More vulnerabilities in widely deployed software](https://lwn.net/Articles/1102044/)&quot;">​</a></h3><p><em>daroc｜lwn</em></p><p>Node.js 发布多个安全更新，修复影响使用 Brotli 压缩程序的远程代码执行漏洞；musl libc 项目也宣布一个越界写漏洞，可能导致远程代码执行（尚未有实际演示）。提醒编译语言生态同样存在供应链安全风险。</p><blockquote><p><strong>学习价值</strong>：帮助学习者建立对用户态基础库安全风险的认知，musl 越界写问题与内核内存安全话题相关联。</p></blockquote><h3 id="hash-based-module-integrity-for-reproducible-distributions-1" tabindex="-1"><a href="https://lwn.net/Articles/1100026/" target="_blank" rel="noreferrer">[$] Hash-based module integrity for reproducible distributions</a> <a class="header-anchor" href="#hash-based-module-integrity-for-reproducible-distributions-1" aria-label="Permalink to &quot;[[$] Hash-based module integrity for reproducible distributions](https://lwn.net/Articles/1100026/)&quot;">​</a></h3><p><em>jake｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Thomas Weißschuh 在 2026 Linux Plumbers Conference 上介绍了基于哈希的内核模块完整性校验补丁：在保证可复现构建（reproducible builds）的前提下，为内核模块提供完整性保证。补丁集历经多次修订，他还讨论了后续可能的改进方向。</p><blockquote><p><strong>学习价值</strong>：深入展示 modules 完整性验证与 reproducible builds 的结合设计，是理解内核供应链安全的优秀案例。</p></blockquote><h3 id="understanding-nix-flakes" tabindex="-1"><a href="https://lwn.net/Articles/1094226/" target="_blank" rel="noreferrer">[$] Understanding Nix flakes</a> <a class="header-anchor" href="#understanding-nix-flakes" aria-label="Permalink to &quot;[[$] Understanding Nix flakes](https://lwn.net/Articles/1094226/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Nix flakes 是 Nix 包管理工具的实验性特性，旨在以更自包含、可复现的方式构建项目。尽管仍是实验状态，许多开源项目已发布 flake.nix 文件提供预定义开发环境与构建自动化，但其稳定化路径仍不确定。</p><blockquote><p><strong>学习价值</strong>：对使用 Nix 构建可复现内核开发环境的读者有帮助，但与内核内部机制关联较弱。</p></blockquote><h3 id="php-patches-released-for-two-critical-rces" tabindex="-1"><a href="https://lwn.net/Articles/1102014/" target="_blank" rel="noreferrer">PHP patches released for two critical RCEs</a> <a class="header-anchor" href="#php-patches-released-for-two-critical-rces" aria-label="Permalink to &quot;[PHP patches released for two critical RCEs](https://lwn.net/Articles/1102014/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>PHP 发布 8.5.12、8.4.27、8.3.36 和 8.2.35 版本，修复两个可被未认证远程代码执行的关键漏洞（CVE-2026-109618 等）。所有处理 Web 请求的 PHP 安装均受影响，其中 mod_php 风险最高，已有在应用代码运行前即可触发的利用演示。</p><blockquote><p><strong>学习价值</strong>：属于用户态运行时的高危漏洞通告，内核学习者可借此对比解释器 OOM 处理与内核内存管理的差异。</p></blockquote><h3 id="four-stable-kernels-for-wednesday" tabindex="-1"><a href="https://lwn.net/Articles/1101758/" target="_blank" rel="noreferrer">Four stable kernels for Wednesday</a> <a class="header-anchor" href="#four-stable-kernels-for-wednesday" aria-label="Permalink to &quot;[Four stable kernels for Wednesday](https://lwn.net/Articles/1101758/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Greg Kroah-Hartman 宣布发布 7.2.12、6.18.58、6.12.114 和 6.6.160 四个稳定版内核，每个版本都包含多项重要修复，建议用户升级。</p><blockquote><p><strong>学习价值</strong>：常规稳定版发布通告，可用于跟踪各长期维护分支的活跃度与生命周期状态。</p></blockquote><h3 id="security-updates-for-wednesday" tabindex="-1"><a href="https://lwn.net/Articles/1102005/" target="_blank" rel="noreferrer">Security updates for Wednesday</a> <a class="header-anchor" href="#security-updates-for-wednesday" aria-label="Permalink to &quot;[Security updates for Wednesday](https://lwn.net/Articles/1102005/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>AlmaLinux、Debian、Fedora 等发行版发布安全更新，涉及 kernel、kernel-rt、openssh、glibc、wireshark、postgresql 等大量软件包，修复各自的安全漏洞。</p><blockquote><p><strong>学习价值</strong>：发行版安全更新汇总，可关注其中 kernel 与 kernel-rt 条目以了解近期稳定分支的安全修复动向。</p></blockquote><h3 id="linux-7-4-begins-landing-patches-to-speed-up-the-kernel-build-process-1" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-Kbuild" target="_blank" rel="noreferrer">Linux 7.4 Begins Landing Patches To Speed Up The Kernel Build Process</a> <a class="header-anchor" href="#linux-7-4-begins-landing-patches-to-speed-up-the-kernel-build-process-1" aria-label="Permalink to &quot;[Linux 7.4 Begins Landing Patches To Speed Up The Kernel Build Process](https://www.phoronix.com/news/Linux-7.4-Kbuild)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Arm 工程师 Lorenzo Stoakes 编写的一批补丁已开始合入 Linux 7.4，旨在加速内核构建过程，可显著缩短内核构建时间。</p><blockquote><p><strong>学习价值</strong>：对关注内核构建系统（Kbuild）优化与开发者日常工作流的学习者有直接实用价值。</p></blockquote><h3 id="linus-torvalds-eliminates-unsafe-get-user-put-user-functions-in-linux-7-4-1" tabindex="-1"><a href="https://www.phoronix.com/news/Linus-Kills-Get-Put-User-Linux" target="_blank" rel="noreferrer">Linus Torvalds Eliminates Unsafe __get_user() &amp; __put_user() Functions In Linux 7.4</a> <a class="header-anchor" href="#linus-torvalds-eliminates-unsafe-get-user-put-user-functions-in-linux-7-4-1" aria-label="Permalink to &quot;[Linus Torvalds Eliminates Unsafe __get_user() &amp; __put_user() Functions In Linux 7.4](https://www.phoronix.com/news/Linus-Kills-Get-Put-User-Linux)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Linus Torvalds 在 Linux 7.4 中移除了历史上不安全的 __get_user() 和 __put_user() 内核函数。这些函数缺少 access_ok() 地址校验，容易被误用导致安全问题。此次清理是 Linus 近期亲自提交补丁（部分借助 Claude Code 辅助）的延续。</p><blockquote><p><strong>学习价值</strong>：展示了内核 API 安全演进的典型案例，学习者可借此理解 user space 内存访问接口的安全边界与历史包袱清理过程。</p></blockquote><h3 id="linux-7-4-kernel-crypto-library-enjoying-optimized-aes-implementations-on-x86-risc-v" tabindex="-1"><a href="https://www.phoronix.com/news/Linux-7.4-Crypto-Library" target="_blank" rel="noreferrer">Linux 7.4 Kernel Crypto Library Enjoying Optimized AES Implementations On x86 &amp; RISC-V</a> <a class="header-anchor" href="#linux-7-4-kernel-crypto-library-enjoying-optimized-aes-implementations-on-x86-risc-v" aria-label="Permalink to &quot;[Linux 7.4 Kernel Crypto Library Enjoying Optimized AES Implementations On x86 &amp; RISC-V](https://www.phoronix.com/news/Linux-7.4-Crypto-Library)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Google 工程师 Eric Biggers 正在将 x86/x86_64 和 RISC-V 上多种 AES 模式的优化实现迁移到 lib/crypto 内核加密库中。这使 lib/crypto 的使用者也能享受硬件加速带来的性能提升。该工作属于内核 crypto subsystem 的持续性能优化。</p><blockquote><p><strong>学习价值</strong>：有助于了解内核加密子系统的架构分层（lib/crypto vs crypto API）以及不同架构上 AES 硬件指令优化的实现方式。</p></blockquote><h3 id="php-updates-released-for-two-critical-code-execution-vulnerabilities" tabindex="-1"><a href="https://www.phoronix.com/news/PHP-New-Critical-CVEs-October" target="_blank" rel="noreferrer">PHP Updates Released For Two Critical Code Execution Vulnerabilities</a> <a class="header-anchor" href="#php-updates-released-for-two-critical-code-execution-vulnerabilities" aria-label="Permalink to &quot;[PHP Updates Released For Two Critical Code Execution Vulnerabilities](https://www.phoronix.com/news/PHP-New-Critical-CVEs-October)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>PHP 发布 8.5.12、8.4.27、8.3.36 和 8.2.35 版本，修复两个可导致未认证远程代码执行的关键漏洞。服务器管理员被建议立即更新。该漏洞与 Linux 内核无关。</p><blockquote><p><strong>学习价值</strong>：属于用户态软件安全公告，对内核学习者价值有限，仅可作为系统安全意识参考。</p></blockquote>',136)])])}const m=r(o,[["render",l]]);export{d as __pageData,m as default};
